/// <summary>
/// Serivce class for adding a prodcution finish request and post an finish report
/// </summary>
public class AVARUMProdImportFinishService
{
}

Method.Source:
/// <summary>
/// Adds a prodcution finish request and post an finish report
/// </summary>
/// <param name = "_prodId">Production number</param>
/// <param name = "_qty">Quantity</param>
/// <param name = "_QtyKg">Quantity in Kg</param>
/// <param name = "_prodDate">Production date</param>
/// <param name = "_licensePlateId">License Plate Id</param>
/// <param name = "_endJob">true if end job</param>
/// <returns>true if successfully posted</returns>
public boolean finishProduction(ProdId _prodId, Qty _qty, Qty _QtyKg, TransDate _prodDate, WHSLicensePlateId _licensePlateId, boolean _endJob)
{
    boolean rc=true;

    AVARUMProdImportFinishTable locAVARUMProdImportFinishTable;

    ttsbegin;
    locAVARUMProdImportFinishTable.clear();
    locAVARUMProdImportFinishTable.initValue();
    locAVARUMProdImportFinishTable.ProdId=_prodId;
    locAVARUMProdImportFinishTable.Qty=_qty;
    locAVARUMProdImportFinishTable.QtyKg=_qtyKg;
    locAVARUMProdImportFinishTable.ProdDate=_prodDate;
    locAVARUMProdImportFinishTable.LicensePlateId=_licensePlateId;
    locAVARUMProdImportFinishTable.EndJob=_endJob;
    locAVARUMProdImportFinishTable.JobStatus=parmJobStatus::Waiting;
    locAVARUMProdImportFinishTable.insert();
    ttscommit;

    rc=AVARUMProdImportFinishManager::postFinish(locAVARUMProdImportFinishTable);

    return rc;
}

/// <summary>
/// Create a object for testing
/// </summary>
/// <returns>Object itself</returns>
static public AVARUMProdImportFinishService construct()
{
    return new AVARUMProdImportFinishService();
}
